#!/bin/bash
cd "$(dirname "$0")"
~/.local/bin/mflux-generate-z-image-turbo -q 4 --low-ram --steps 8 --width 832 --height 1216 --seed 23 --prompt "Photorealistic full-length portrait of an eccentric flamboyant film director with huge swagger, a charming roguish bohemian showman in his 40s, playful mischievous grin, one eyebrow raised, dark tousled shoulder-length hair under a battered dark fedora hat, smoky eyeliner, short goatee with two small beads, layered silver rings and necklaces, loose white linen shirt half open with a long burgundy silk scarf, vintage brown leather waistcoat, holding a golden megaphone in one hand and gesturing theatrically with the other, standing with a cocky tilted hip pose, full body head to boots, plain solid very dark navy studio background, gold rim light, cinematic lighting, high-end editorial photography" --output max2.png >/dev/null 2>&1 && echo "made max2"
